CREATE TABLE b3_security_definitions(snapshot_id UUID NOT NULL,source_member_id VARCHAR(36) NOT NULL,record_index BIGINT NOT NULL,symbol TEXT NOT NULL,security_id TEXT NOT NULL,security_id_source TEXT,security_exchange TEXT,isin_number TEXT,product TEXT,cfi_code TEXT,security_group TEXT,security_type TEXT,security_sub_type TEXT,maturity_month_year TEXT,maturity_date TEXT,issue_date TEXT,country_of_issue TEXT,put_or_call TEXT,strike_price NUMERIC,strike_currency TEXT,exercise_style TEXT,contract_multiplier NUMERIC,security_desc TEXT,contract_settl_month TEXT,dated_date TEXT,settl_type TEXT,settl_date TEXT,price_divisor NUMERIC,min_price_increment NUMERIC,tick_size_denominator TEXT,min_order_qty NUMERIC,max_order_qty NUMERIC,multi_leg_model TEXT,multi_leg_price_method TEXT,start_date TEXT,end_date TEXT,currency TEXT,settl_currency TEXT,security_strategy_type TEXT,asset TEXT,no_shares_issued NUMERIC,security_validity_timestamp TEXT,market_segment_id TEXT,governance_indicator TEXT,corporate_action_event_id TEXT,security_match_type TEXT,implied_market_indicator TEXT,min_cross_qty NUMERIC,min_trade_vol NUMERIC,clearing_house_id TEXT,business_hash TEXT NOT NULL,PRIMARY KEY(snapshot_id,source_member_id,record_index),FOREIGN KEY(snapshot_id,source_member_id,record_index) REFERENCES b3_registry_records(snapshot_id,source_member_id,record_index));
CREATE TABLE b3_security_definition_appl_ids(snapshot_id UUID NOT NULL,source_member_id VARCHAR(36) NOT NULL,record_index BIGINT NOT NULL,group_index INT NOT NULL,appl_id TEXT NOT NULL,PRIMARY KEY(snapshot_id,source_member_id,record_index,group_index),FOREIGN KEY(snapshot_id,source_member_id,record_index) REFERENCES b3_registry_records(snapshot_id,source_member_id,record_index));
CREATE TABLE b3_security_definition_underlying(snapshot_id UUID NOT NULL,source_member_id VARCHAR(36) NOT NULL,record_index BIGINT NOT NULL,group_index INT NOT NULL,symbol TEXT,security_id TEXT,security_id_source TEXT,security_exchange TEXT,index_pct NUMERIC,index_theoretical_qty NUMERIC,PRIMARY KEY(snapshot_id,source_member_id,record_index,group_index),FOREIGN KEY(snapshot_id,source_member_id,record_index) REFERENCES b3_registry_records(snapshot_id,source_member_id,record_index));
CREATE TABLE b3_security_definition_attributes(snapshot_id UUID NOT NULL,source_member_id VARCHAR(36) NOT NULL,record_index BIGINT NOT NULL,group_index INT NOT NULL,attribute_type TEXT NOT NULL,value TEXT NOT NULL,PRIMARY KEY(snapshot_id,source_member_id,record_index,group_index),FOREIGN KEY(snapshot_id,source_member_id,record_index) REFERENCES b3_registry_records(snapshot_id,source_member_id,record_index));
CREATE TABLE b3_security_definition_legs(snapshot_id UUID NOT NULL,source_member_id VARCHAR(36) NOT NULL,record_index BIGINT NOT NULL,group_index INT NOT NULL,symbol TEXT,security_id TEXT,security_id_source TEXT,security_exchange TEXT,security_type TEXT,side TEXT,ratio_quantity NUMERIC,PRIMARY KEY(snapshot_id,source_member_id,record_index,group_index),FOREIGN KEY(snapshot_id,source_member_id,record_index) REFERENCES b3_registry_records(snapshot_id,source_member_id,record_index));
CREATE TABLE b3_security_definition_tick_rules(snapshot_id UUID NOT NULL,source_member_id VARCHAR(36) NOT NULL,record_index BIGINT NOT NULL,group_index INT NOT NULL,start_price NUMERIC,end_price NUMERIC,increment NUMERIC,rule_type TEXT,PRIMARY KEY(snapshot_id,source_member_id,record_index,group_index),FOREIGN KEY(snapshot_id,source_member_id,record_index) REFERENCES b3_registry_records(snapshot_id,source_member_id,record_index));
CREATE TABLE b3_security_definition_lot_rules(snapshot_id UUID NOT NULL,source_member_id VARCHAR(36) NOT NULL,record_index BIGINT NOT NULL,group_index INT NOT NULL,lot_type TEXT,min_lot_size NUMERIC,PRIMARY KEY(snapshot_id,source_member_id,record_index,group_index),FOREIGN KEY(snapshot_id,source_member_id,record_index) REFERENCES b3_registry_records(snapshot_id,source_member_id,record_index));
